// EDIT THESE VALUES ONCE, then activate the workflow
return [{ json: {
  "sheetId": "PASTE_SHEET_ID",
  "company": "Your Property Management",
  "managerEmail": "manager@yourpm.com",
  "fromName": "Your Name",
  "followUpHours": 24,
  "maxFollowUps": 2
} }];

const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

const out = [];
for (const it of $input.all()) { const r = it.json; if (!r['Vendor email'] || /^(yes|y|true|confirmed)$/i.test(String(r['Vendor confirmed']||''))) continue;
  const st = String(r['Status']||'').toLowerCase(); const wo = `Ticket ${r['Ticket']} - ${r['Unit']}`;
  if (st === 'assigned' && !r['Dispatched']) { out.push({ json: { row_number: r.row_number, kind: 'dispatch', to: r['Vendor email'],
    subject: `Work order: ${wo} (${r['Priority'] || 'routine'})`,
    body: `Hello ${r['Vendor'] || ''},\n\nPlease handle this work order:\n\nTicket: ${r['Ticket']}\nUnit: ${r['Unit']}\nPriority: ${r['Priority'] || 'routine'}\nIssue: ${r['Request']}\n\nPlease reply to confirm and share your earliest date.\n\n${C.fromName}\n${C.company}`, n: 0 } }); continue; }
  const sent = parse(r['Dispatched']); const n = num(r['Follow-ups']);
  if (sent && (Date.now() - sent) / 36e5 >= C.followUpHours * (n + 1)) {
    if (n < C.maxFollowUps) out.push({ json: { row_number: r.row_number, kind: 'chase', to: r['Vendor email'], subject: `Following up: ${wo}`,
      body: `Hello ${r['Vendor'] || ''},\n\nFollowing up on work order ${r['Ticket']} (${r['Unit']}): ${r['Request']}.\nCan you confirm a date today?\n\n${C.fromName}`, n: n + 1 } });
    else if (n === C.maxFollowUps) out.push({ json: { row_number: r.row_number, kind: 'escalate', to: C.managerEmail, subject: `Vendor not responding: ${wo}`,
      body: `${r['Vendor']} has not confirmed ticket ${r['Ticket']} (${r['Unit']}) after ${n} follow-ups. Consider reassigning.\nIssue: ${r['Request']}`, n: n + 1 } });
  }
}
return out;
